    ((SELECT id FROM categoria WHERE slug = 'componentes'), 'Memoria 32 GB DDR5 RGB (2x16)', 'memoria-32-gb-ddr5-rgb-2x16', 2199, 12, 2, 'ram', 'ram-ddr5-rgb', '[["Capacidad", "32 GB (2 × 16 GB)"], ["Tipo", "DDR5"], ["Velocidad", "6000 MT/s"], ["Iluminación", "RGB"]]', '6000 MHz con iluminación sincronizable.'),
